struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key;
    int ret;

    if (!ctx || !dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    key = alloc_key(callout_len);
    if (!key)
        return ERR_PTR(-ENOMEM);

    key->callout_info = kmemdup(callout_info, callout_len, GFP_KERNEL);
    if (!key->callout_info) {
        ret = -ENOMEM;
        goto error_alloc_callout;
    }

    key->aux = aux;
    key->flags = flags;

    ret = key_instantiate(key, ctx);
    if (ret < 0)
        goto error_instantiate;

    ret = link_key_to_keyring(dest_keyring, key);
    if (ret < 0)
        goto error_link;

    return key;

error_link:
    unlink_key(key);
error_instantiate:
    free_key_info(key->callout_info);
error_alloc_callout:
    kfree(key);
    return ERR_PTR(ret);
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key;
    int ret;

    /* Validate keyring type if necessary */
    if (!dest_keyring || !S_ISDIR(dest_keyring->usage)) {
        return ERR_PTR(-EINVAL);
    }

    /* Allocate a new key */
    key = key_alloc(&key_type_user, callout_info, callout_len, current_cred(),
                    flags, NULL, NULL);
    if (IS_ERR(key)) {
        return key;
    }

    /* Set up the key with callout and auxiliary data */
    ret = key_instantiate_and_link(key, callout_info, callout_len, aux,
                                   dest_keyring);
    if (ret < 0) {
        key_put(key);
        return ERR_PTR(ret);
    }

    return key;
}

struct key *construct_key_and_link(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *new_key;
    int ret;

    if (!ctx || !dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    new_key = key_alloc(&key_type_user, NULL, current_fsuid(), current_fsgid(), flags, NULL, NULL);
    if (IS_ERR(new_key)) {
        return new_key;
    }

    ret = key_instantiate_and_link(new_key, callout_info, callout_len, dest_keyring, aux);
    if (ret < 0) {
        key_put(new_key);
        return ERR_PTR(ret);
    }

    return new_key;
}
